WITH flattened AS (SELECT id, customer_id, created_at, coupon_codes, pos, elem.product_id, elem.qty, elem.price, elem.promo FROM carts LATERAL VIEW POSEXPLODE(items) li AS pos, elem) SELECT DATE_TRUNC('HOUR', created_at) AS hour_window, DATE_TRUNC('DAY', created_at) AS activity_day, SUM(price) AS total_price, COUNT(DISTINCT customer_id) AS distinct_customer_ids, PERCENTILE_APPROX(price, 0.5) AS price_p50, SUM(CASE WHEN promo = 'SPRING10' THEN pos ELSE 0 END) AS spring10_pos, COUNT(CASE WHEN promo = 'SPRING10' THEN 1 END) AS spring10_count, MAX(created_at) AS last_seen, GROUPING_ID() AS grouping_id FROM flattened GROUP BY GROUPING SETS ((DATE_TRUNC('HOUR', created_at), DATE_TRUNC('DAY', created_at)), (DATE_TRUNC('HOUR', created_at)), ()) HAVING COUNT(CASE WHEN promo = 'SPRING10' THEN 1 END) >= 1 ORDER BY price_p50 NULLS LAST;
